function validateDomain(s){
  s=(String(s||'')).trim().toLowerCase();
  if(!s) return {valid:false, reason:'empty'};
  if(s.length>253) return {valid:false, reason:'too long'};
  if(!/^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)*$/.test(s)) return {valid:false, reason:'format'};
  var labels=s.split('.'); var tld=labels[labels.length-1];
  if(tld.length<2) return {valid:false, reason:'tld short'};
  return {valid:true, tld:tld, labels:labels.length};
}

var EXPORTS={validateDomain:validateDomain};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DomainForgePure = EXPORTS; }
